/*
 * Minimal ki18n_export.h stub for C++ skeleton build.
 * In upstream ki18n this is generated by ECM (ecm_generate_export_header).
 * For ABI compatibility we only need the export macros here.
 */

#ifndef KI18N_EXPORT_H
#define KI18N_EXPORT_H

#if defined(_WIN32) || defined(_WIN64)
  #ifdef KI18N_BUILDING_LIBRARY
    #define KI18N_EXPORT __declspec(dllexport)
  #else
    #define KI18N_EXPORT __declspec(dllimport)
  #endif
#else
  #define KI18N_EXPORT __attribute__((visibility("default")))
#endif

/* Upstream defines KI18N_ENABLE_DEPRECATED_SINCE via ECM; for skeleton builds
 * we always enable deprecated methods to maintain ABI compatibility. */
#ifndef KI18N_ENABLE_DEPRECATED_SINCE
#define KI18N_ENABLE_DEPRECATED_SINCE(maj, min) 1
#endif

#ifndef KI18N_DEPRECATED_VERSION
#define KI18N_DEPRECATED_VERSION(maj, min, msg) [[deprecated(msg)]]
#endif

#endif // KI18N_EXPORT_H


